        float[] vertices = polygonVertices.get(name);
        boolean result = Intersector.isPointInPolygon(vertices, x, y);

        // Preserve the input formatting for coordinates
        System.out.println("CONTAINS " + name + " " + tokens[2] + " " + tokens[3] + " " + result);
    }

