            throw new IllegalArgumentException("Invalid number format");
        }

        Vector2 a = new Vector2(ax, ay);
        Vector2 b = new Vector2(bx, by);
        Vector2 c = new Vector2(cx, cy);
        Vector2 d = new Vector2(dx, dy);
        Vector2 intersection = new Vector2();

