        if (!polygons.containsKey(name)) {
            throw new IllegalArgumentException("Undefined polygon: " + name);
        }

        Polygon poly = polygons.get(name);
        float area = poly.area();

        System.out.println("AREA " + name + " " + String.format(Locale.ROOT, "%.3f", area));
    }

