    private void handlePoly(String[] tokens, int lineNumber) {
        if (tokens.length < 7) {
            throw new IllegalArgumentException("POLY requires at least 3 vertices (6 coordinates)");
        }

        String name = tokens[1];
        int numCoords = tokens.length - 2;
        if (numCoords < 6 || numCoords % 2 != 0) {
            throw new IllegalArgumentException("POLY requires an even number of coordinates (at least 6)");
        }

        float[] vertices = new float[numCoords];
        try {
            for (int i = 0; i < numCoords; i++) {
                vertices[i] = Float.parseFloat(tokens[2 + i]);
            }
        } catch (NumberFormatException e) {
            throw new IllegalArgumentException("Invalid number format");
