    }

    private void handleSegments(String[] tokens, int lineNumber) {
        if (tokens.length != 9) {
            throw new IllegalArgumentException("SEGMENTS requires exactly 8 coordinates");
        }

        float ax, ay, bx, by, cx, cy, dx, dy;
