            // Skip blank lines and comments
            if (trimmed.isEmpty() || trimmed.startsWith("#")) {
                continue;
            }

            try {
                processLine(trimmed, lineNumber);
            } catch (Exception e) {
                // Extract command or reason
                String[] tokens = trimmed.split("\\s+");
                String command = tokens.length > 0 ? tokens[0] : "UNKNOWN";
                System.out.println("ERROR " + lineNumber + " " + command);
            }
        }
    }

    private void processLine(String line, int lineNumber) {
        String[] tokens = line.split("\\s+");
        String command = tokens[0];

        switch (command) {
            case "POLY":
                handlePoly(tokens, lineNumber);
                break;
            case "OVERLAP":
                handleOverlap(tokens, lineNumber);
                break;
            case "CONTAINS":
                handleContains(tokens, line, lineNumber);
                break;
            case "SEGMENTS":
                handleSegments(tokens, lineNumber);
                break;
            case "AREA":
                handleArea(tokens, lineNumber);
                break;
            default:
                System.out.println("ERROR " + lineNumber + " " + command);
        }
    }

    private void handlePoly(String[] tokens, int lineNumber) {
        if (tokens.length < 7) {
            throw new IllegalArgumentException("POLY requires at least 3 vertices (6 coordinates)");
        }

        String name = tokens[1];
