        }

        float x, y;
        try {
            x = Float.parseFloat(tokens[2]);
            y = Float.parseFloat(tokens[3]);
        } catch (NumberFormatException e) {
            throw new IllegalArgumentException("Invalid number format");
        }

        float[] vertices = polygonVertices.get(name);
